import logging
import re
from typing import Any, Dict, List, Tuple

from backend.schemas.conversation import CitationItem

logger = logging.getLogger("ekn.citations")


class CitationService:
    """Validates citations generated by the LLM against actual retrieved evidence.

    Guarantees that:
    1. The LLM never invents or overrides document names or page numbers.
    2. Citation markers (e.g. [E1], [E2]) are mapped strictly to verifiable retrieval chunks.
    3. Hallucinated or out-of-bounds citations (e.g. [E99]) are purged and flagged.
    """

    CITATION_PATTERN = re.compile(r"\[(.*?)\]")
    EVIDENCE_ID_PATTERN = re.compile(r"\bE(\d+)\b")

    def extract_cited_evidence_ids(self, text: str) -> List[str]:
        """Extract all unique evidence IDs cited inside square brackets (e.g. [E1], [E1, E2])."""
        if not text:
            return []

        cited_ids: List[str] = []
        bracket_contents = self.CITATION_PATTERN.findall(text)

        for content in bracket_contents:
            matches = self.EVIDENCE_ID_PATTERN.findall(content)
            for m in matches:
                cited_ids.append(f"E{m}")

        # Preserve order while removing duplicates
        return list(dict.fromkeys(cited_ids))

    def validate_citations(
        self,
        answer_text: str,
        evidence_map: Dict[str, Dict[str, Any]],
    ) -> Tuple[List[CitationItem], List[str]]:
        """Validate all citations in the generated answer against the ground-truth evidence pool.

        Args:
            answer_text: Raw answer markdown generated by the LLM.
            evidence_map: Dictionary mapping stable IDs (e.g. 'E1') to retrieved chunk metadata.

        Returns:
            Tuple of:
            - validated_citations: List of verified CitationItem objects with exact page ranges and excerpts.
            - validation_issues: List of diagnostic warnings (e.g. invalid or hallucinated citation IDs).
        """
        cited_ids = self.extract_cited_evidence_ids(answer_text)
        validated_citations: List[CitationItem] = []
        validation_issues: List[str] = []

        for cid in cited_ids:
            if cid in evidence_map:
                ev = evidence_map[cid]
                citation_item = CitationItem(
                    citation_id=cid,
                    document_id=ev.get("document_id", ""),
                    filename=ev.get("original_filename", ""),
                    page_start=ev.get("page_start", 1),
                    page_end=ev.get("page_end", 1),
                    section=ev.get("section_title", ""),
                    excerpt=ev.get("text", "")[:300].strip(),
                    family_title=ev.get("family_title"),
                    version_number=ev.get("version_number", 1),
                    version_status=ev.get("version_status", "current"),
                    is_current=ev.get("is_current", True),
                )
                validated_citations.append(citation_item)
            else:
                issue = f"Citation '{cid}' cited by model does not exist in retrieved evidence pool."
                logger.warning(issue)
                validation_issues.append(issue)

        return validated_citations, validation_issues


citation_service = CitationService()
